describe('a support conversation after the socket closes', () => {
  it('is still readable from MongoDB by a store that never saw the socket, with the question and the answer', async () => {
    const sessionId = await askOneQuestionThenCloseSocket(await accessToken());
    const reader = createMongoSessionStore(mongo);

    const stored = await reader.get(sessionId);
    await reader.close();

    expect(stored).toMatchObject({
      sessionId,
      entries: expect.arrayContaining([
        expect.objectContaining({role: 'user', content: 'Hvor er min booking?'}),
        expect.objectContaining({role: 'assistant'}),
      ]),
    });
  });

  it('stores the question but no authorization header, bearer token or jwt', async () => {
    const sessionId = await askOneQuestionThenCloseSocket(await accessToken());
    const reader = createMongoSessionStore(mongo);

    const serialized = JSON.stringify(await reader.get(sessionId));
    await reader.close();

    expect({
      question: serialized.includes('Hvor er min booking?'),
      credential: /authorization|bearer|ey[A-Za-z0-9_-]{10}/i.test(serialized),
    }).toEqual({question: true, credential: false});
  });

  it('is gone from both the document and the cache after delete, and a repeat delete reports nothing removed', async () => {
    const sessionId = await askOneQuestionThenCloseSocket(await accessToken());
    const store = createMongoSessionStore(mongo);

    const erased = await store.delete(sessionId);
    const afterErase = await store.get(sessionId);
    const repeat = await store.delete(sessionId);
    await store.close();

    expect({erased, afterErase, repeat}).toEqual({
      erased: true,
      afterErase: undefined,
      repeat: false,
    });
  });
});

